import{_ as n,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Agent 原理:它到底在做什么,什么时候会失败","description":"前五篇讲的是「怎么做」——MCP、多 Agent、记忆、反思。这一篇讲「为什么」:Agent 的运行机制、第一性原理,以及在没有框架的时候也该知道的事。","frontmatter":{},"headers":[],"relativePath":"agent/agent-advanced/6-agent-principles.md","filePath":"agent/agent-advanced/6-agent-principles.md","lastUpdated":1793930980000}'),s={name:"agent/agent-advanced/6-agent-principles.md"};function d(o,t,i,g,l,h){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="agent-原理-它到底在做什么-什么时候会失败" tabindex="-1">Agent 原理:它到底在做什么,什么时候会失败 <a class="header-anchor" href="#agent-原理-它到底在做什么-什么时候会失败" aria-label="Permalink to &quot;Agent 原理:它到底在做什么,什么时候会失败&quot;">​</a></h1><blockquote><p>前五篇讲的是「<strong>怎么做</strong>」——MCP、多 Agent、记忆、反思。这一篇讲「<strong>为什么</strong>」:Agent 的运行机制、第一性原理,以及在没有框架的时候也该知道的事。</p><p>面试里最值钱的一句话是「<strong>Agent 没什么高深的技术,它就是 LLM 加工具调用加一个循环</strong>」。但要把这个「没什么高深」讲透,才显得你真懂 —— 而不是读过几篇教程。</p></blockquote><h2 id="一、agent-的最小模型" tabindex="-1">一、Agent 的最小模型 <a class="header-anchor" href="#一、agent-的最小模型" aria-label="Permalink to &quot;一、Agent 的最小模型&quot;">​</a></h2><h3 id="_1-1-一句话定义" tabindex="-1">1.1 一句话定义 <a class="header-anchor" href="#_1-1-一句话定义" aria-label="Permalink to &quot;1.1 一句话定义&quot;">​</a></h3><blockquote><p><strong>Agent = LLM(决策) + 工具(执行) + 状态(记忆) + 循环(重复直到目标达成)</strong></p></blockquote><h3 id="_1-2-四个部件-四个不同的问题" tabindex="-1">1.2 四个部件,四个不同的问题 <a class="header-anchor" href="#_1-2-四个部件-四个不同的问题" aria-label="Permalink to &quot;1.2 四个部件,四个不同的问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部件</th><th>解决的问题</th><th>工程形态</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>「下一步做什么」的判断</td><td>一个函数调用:输入 prompt + 工具列表,输出「文本」或「工具调用」</td></tr><tr><td><strong>工具</strong></td><td>「做」的能力</td><td><strong>确定性代码</strong>,不是 LLM</td></tr><tr><td><strong>状态</strong></td><td>「记住已经发生了什么」</td><td>显式的 state 对象,不是模型的隐式记忆</td></tr><tr><td><strong>循环</strong></td><td>「直到够了为止」</td><td>while + max_iterations</td></tr></tbody></table><p><strong>关键认知:Agent 的工程量绝大部分在「工具」和「状态」,不在「决策」。</strong></p><p>决策质量受模型能力限制,你优化不了;你能优化的是:<strong>给它更好的工具、更准的状态、更清晰的边界</strong>。</p><h3 id="_1-3-llm-在循环里到底能决定什么" tabindex="-1">1.3 LLM 在循环里到底能决定什么 <a class="header-anchor" href="#_1-3-llm-在循环里到底能决定什么" aria-label="Permalink to &quot;1.3 LLM 在循环里到底能决定什么&quot;">​</a></h3><p>这是理解 Agent 最关键的一点。LLM 每轮只能输出三样东西:</p><ol><li><strong>调哪个工具</strong>(以及参数)</li><li><strong>是否结束</strong>(返回最终答案,还是继续下一轮)</li><li><strong>下一轮的输入</strong>(把工具结果拼回上下文)</li></ol><p><strong>它不能决定的</strong>:工具内部怎么实现、数据从哪来、业务规则是什么。</p><blockquote><p>所以「Agent 能力很强」是一种错觉。真正强的是<strong>工具集设计得好</strong>。</p><p>给 Agent 一个 <code>query_users(sql)</code> 和只给它一个 <code>search(keyword)</code>,能力差一个量级 —— 后者只能靠猜 SQL 文本。</p><p><strong>推论:做 Agent 平台,一半的工程量在写工具,不是在调 prompt。</strong></p></blockquote><h3 id="_1-4-循环的四种终止方式" tabindex="-1">1.4 循环的四种终止方式 <a class="header-anchor" href="#_1-4-循环的四种终止方式" aria-label="Permalink to &quot;1.4 循环的四种终止方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>终止方式</th><th>判定方式</th><th>用在哪</th></tr></thead><tbody><tr><td><strong>目标达成</strong></td><td>LLM 返回最终答案</td><td>常规路径</td></tr><tr><td><strong>步数上限</strong></td><td><code>max_iterations</code></td><td>必备兜底</td></tr><tr><td><strong>成本上限</strong></td><td>累计 token / 卡时</td><td>Agent 会跑飞时的兜底</td></tr><tr><td><strong>人工中断</strong></td><td>HITL 暂停等输入</td><td>高风险动作</td></tr></tbody></table><p><strong>只做前两种的 Agent,迟早会烧钱。</strong> 见第五章的失败模式。</p><h2 id="二、上下文工程-提示词" tabindex="-1">二、上下文工程 &gt; 提示词 <a class="header-anchor" href="#二、上下文工程-提示词" aria-label="Permalink to &quot;二、上下文工程 &gt; 提示词&quot;">​</a></h2><h3 id="_2-1-上下文就是-agent-唯一的工作空间" tabindex="-1">2.1 上下文就是 Agent 唯一的工作空间 <a class="header-anchor" href="#_2-1-上下文就是-agent-唯一的工作空间" aria-label="Permalink to &quot;2.1 上下文就是 Agent 唯一的工作空间&quot;">​</a></h3><p>Agent 的「记忆」就是上下文窗口。<strong>窗口里放什么,直接决定它的行为。</strong> 提示词只是上下文的一部分。</p><h3 id="_2-2-上下文的四个来源" tabindex="-1">2.2 上下文的四个来源 <a class="header-anchor" href="#_2-2-上下文的四个来源" aria-label="Permalink to &quot;2.2 上下文的四个来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>内容</th><th>常见错误</th></tr></thead><tbody><tr><td><strong>指令</strong></td><td>系统提示、角色定义</td><td>越写越长,互相矛盾</td></tr><tr><td><strong>状态</strong></td><td>已有产出、已完成步骤</td><td>只写「做过什么」,不写「为什么」</td></tr><tr><td><strong>工具结果</strong></td><td>检索 / 查询的返回</td><td>塞满原始 JSON,又长又是噪声</td></tr><tr><td><strong>记忆</strong></td><td>长期知识、用户偏好</td><td>不管相关性,全量注入</td></tr></tbody></table><h3 id="_2-3-三条实用规则" tabindex="-1">2.3 三条实用规则 <a class="header-anchor" href="#_2-3-三条实用规则" aria-label="Permalink to &quot;2.3 三条实用规则&quot;">​</a></h3><p><strong>① 工具结果要摘要后再进上下文</strong></p><p>原始 5000 行 JSON 会挤爆窗口并稀释信号。给 Agent 一个「search → 返回 top-5 摘要」的工具,远好过给它原始查询能力。</p><p><strong>② 状态要写「为什么」</strong></p><blockquote><p>「第 3 镜用角色 v2,因为 v1 的发型和第 2 镜不连续」 比 「第 3 镜用角色 v2」</p><p>有用一个量级。前者让下一个 Agent(或人)能判断要不要相信它。</p></blockquote><p><strong>③ 给 Agent 一个「够用就停」的信号</strong></p><p>让它能回答「我还需要什么」,比让它盲目循环便宜得多 —— 成本上限只有在 Agent 知道目标时才有效。</p><h2 id="三、什么时候不该用-agent" tabindex="-1">三、什么时候<strong>不该</strong>用 Agent <a class="header-anchor" href="#三、什么时候不该用-agent" aria-label="Permalink to &quot;三、什么时候**不该**用 Agent&quot;">​</a></h2><p>这一节比「怎么用 Agent」值钱。</p><table tabindex="0"><thead><tr><th>场景</th><th>更好的选择</th><th>为什么</th></tr></thead><tbody><tr><td>流程固定、步骤确定</td><td><strong>写代码</strong>(Workflow)</td><td>Agent 只会增加不确定性</td></tr><tr><td>需要 100% 可复现</td><td>确定性代码 + 校验</td><td>Agent 有随机性</td></tr><tr><td>单步就能做完</td><td>直接调一次 LLM</td><td>加循环纯属浪费</td></tr><tr><td>错误代价高且不可逆</td><td>人工主导,Agent 只出建议</td><td>试错成本太高</td></tr><tr><td>强依赖精确计算</td><td>让 LLM <strong>输出参数</strong>,让代码去算</td><td>LLM 不擅长算数</td></tr></tbody></table><blockquote><p><strong>一句话判据:如果一个流程你能用 if/else 写出来,就先用 if/else。</strong></p><p>Agent 的价值只在<strong>路径不确定</strong>的地方 —— 分镜怎么拆、这个镜头该用哪个模型、这段对话到底在问什么。</p></blockquote><h2 id="四、单-agent-还是多-agent" tabindex="-1">四、单 Agent 还是多 Agent <a class="header-anchor" href="#四、单-agent-还是多-agent" aria-label="Permalink to &quot;四、单 Agent 还是多 Agent&quot;">​</a></h2><h3 id="_4-1-先问-能不能用一个-agent-更多工具" tabindex="-1">4.1 先问:能不能用一个 Agent + 更多工具 <a class="header-anchor" href="#_4-1-先问-能不能用一个-agent-更多工具" aria-label="Permalink to &quot;4.1 先问:能不能用一个 Agent + 更多工具&quot;">​</a></h3><p><strong>多 Agent 几乎总是更贵、更慢、更难调试。</strong> 拆分前先确认三件事:</p><ol><li>这个 Agent 的职责是否<strong>真的不同</strong>(不是「同一件事换个角度」)?</li><li>它们的输出是否能<strong>用结构化契约</strong>交接(不是自由文本)?</li><li>失败时能不能<strong>独立重试</strong>(一个挂了不用全部重来)?</li></ol><p>三个都满足,再考虑拆。</p><h3 id="_4-2-协作模式与判据" tabindex="-1">4.2 协作模式与判据 <a class="header-anchor" href="#_4-2-协作模式与判据" aria-label="Permalink to &quot;4.2 协作模式与判据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>拓扑</th><th>什么时候用</th><th>代价</th></tr></thead><tbody><tr><td><strong>Single + Tools</strong></td><td>一个循环</td><td><strong>默认选它</strong></td><td>上下文压力大</td></tr><tr><td><strong>Pipeline</strong></td><td>固定顺序</td><td>阶段清晰、可并行</td><td>早期错误会往下传</td></tr><tr><td><strong>Supervisor</strong></td><td>主管路由</td><td>步骤类型确实不确定</td><td>主管本身是瓶颈</td></tr><tr><td><strong>Swarm / 辩论</strong></td><td>互相通信</td><td>需要多视角对抗</td><td>成本爆炸、难收敛</td></tr></tbody></table><p>各模式的实现见 <a href="./3-multi-agent">Multi-Agent 多智能体系统</a>。</p><h3 id="_4-3-多-agent-真正的难点不是编排-是契约" tabindex="-1">4.3 多 Agent 真正的难点不是编排,是契约 <a class="header-anchor" href="#_4-3-多-agent-真正的难点不是编排-是契约" aria-label="Permalink to &quot;4.3 多 Agent 真正的难点不是编排,是契约&quot;">​</a></h3><p>多数人把多 Agent 理解成「画图连线」。真正难的是三件事:</p><p><strong>① 状态所有权</strong></p><table tabindex="0"><thead><tr><th>状态</th><th>谁能写</th><th>谁能读</th></tr></thead><tbody><tr><td>剧本</td><td>剧本 Agent</td><td>全部</td></tr><tr><td>角色资产</td><td>角色 Agent(人也可改)</td><td>全部</td></tr><tr><td>分镜</td><td>分镜 Agent</td><td>生成 / 一致性 / 剪辑</td></tr><tr><td>任务队列</td><td><strong>只有调度器</strong></td><td>全部</td></tr></tbody></table><p><strong>一个状态只能有一个写入者。</strong> 两个 Agent 都能写同一个状态,结果就是不可复现的竞态 —— 而且这种 bug 极难定位。</p><p><strong>② 交接契约</strong></p><p>Agent 之间的交接必须<strong>结构化、带版本、带理由</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Handoff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BaseModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    version: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 契约版本,升级时能识别旧数据</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    payload: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">dict</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    reason: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 为什么这么判断 —— 下一棒才知道能不能信</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    unresolved: list[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 我不知道的事,显式传下去</span></span></code></pre></div><p>自由文本交接 = 两个 Agent 互相猜。</p><p><strong>③ 裁决</strong></p><p>冲突时谁说了算?<strong>必须显式指定,不能靠模型自觉。</strong></p><h2 id="五、失败模式清单" tabindex="-1">五、失败模式清单 <a class="header-anchor" href="#五、失败模式清单" aria-label="Permalink to &quot;五、失败模式清单&quot;">​</a></h2><p>这一节最值钱 —— 面试官问「你觉得 Agent 哪里容易出问题」,答得出这张表就直接赢了。</p><table tabindex="0"><thead><tr><th>失败模式</th><th>症状</th><th>根因</th><th>对策</th></tr></thead><tbody><tr><td><strong>无限循环</strong></td><td>反复调同一个工具</td><td>目标不清晰 / 没有终止判据</td><td>max_iterations + 成本上限 + 重复调用检测</td></tr><tr><td><strong>级联幻觉</strong></td><td>第一个 Agent 编了数据,后面全信</td><td>下游不校验上游</td><td>每个 Agent 输出都做 schema + 业务双重校验</td></tr><tr><td><strong>上下文污染</strong></td><td>早期错误留在上下文里,越走越歪</td><td>状态没有回滚机制</td><td>关键状态分片,允许丢弃重来</td></tr><tr><td><strong>重复劳动</strong></td><td>两个 Agent 做同一件事</td><td>职责边界模糊</td><td>契约里写清谁负责什么</td></tr><tr><td><strong>局部最优</strong></td><td>每个 Agent 都做对了,合起来很差</td><td>没有全局目标</td><td>Supervisor 或全局评审 Agent</td></tr><tr><td><strong>静默降级</strong></td><td>某步失败后走了降级路径,没人知道</td><td>错误被吞</td><td>失败路径必须显式上报到界面</td></tr><tr><td><strong>成本失控</strong></td><td>一个任务烧掉几百倍预算</td><td>没有成本闸门</td><td>每个 Agent 设 token / 卡时上限</td></tr><tr><td><strong>提示词漂移</strong></td><td>改了 prompt,某条链路行为变了</td><td>没有回归集</td><td>Agent 输出做快照回归测试</td></tr><tr><td><strong>状态竞态</strong></td><td>两个 Agent 写同一状态,结果不可复现</td><td>写入权不明确</td><td>一个状态一个写入者</td></tr></tbody></table><blockquote><p><strong>面试里说得出这张表,比说得出任何框架都值钱。</strong> 因为它证明你<strong>踩过坑</strong>,而不是读过文档。</p></blockquote><h2 id="六、如果只记三句话" tabindex="-1">六、如果只记三句话 <a class="header-anchor" href="#六、如果只记三句话" aria-label="Permalink to &quot;六、如果只记三句话&quot;">​</a></h2><ol><li><strong>Agent = LLM + 工具 + 状态 + 循环</strong>;决定能力上限的是<strong>工具</strong>,不是 prompt。</li><li><strong>能写成 if/else 的就别用 Agent</strong>;Agent 只用在路径不确定的地方。</li><li>多 Agent 的难点不是编排,是<strong>契约、状态所有权和失败恢复</strong>。</li></ol><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><p><strong>Q1:Agent 到底是什么?和普通 LLM 调用有什么区别?</strong></p><blockquote><p>「多了一层循环和状态管理。普通调用是问一次答一次;Agent 是模型自己决定下一步调哪个工具、传什么参数,工具返回结果再喂回去,直到目标达成。真正的区别不在模型,在<strong>工具和状态的设计</strong> —— 很多场景下决定效果的是这两样,不是 prompt。」</p></blockquote><p><strong>Q2:什么时候不该用 Agent?</strong></p><blockquote><p>「流程能写成 if/else 的时候就不该用。或者需要 100% 可复现、错误不可逆、强依赖精确计算的场景 —— 这些该用确定性代码,LLM 只负责输出参数。」</p></blockquote><p><strong>Q3:多 Agent 最难的是什么?</strong></p><blockquote><p>「不是编排,是<strong>契约</strong>。三个点:状态所有权(一个状态只能一个写入者)、交接契约(结构化、带版本、带理由)、冲突裁决(必须显式指定)。这三点没定清楚,画出来的图再漂亮也是不可复现的。」</p></blockquote><p><strong>Q4:Agent 常见的失败模式?</strong></p><blockquote><p>见第五章那张表。现场展开讲三到四个即可,但<strong>要能说清根因和对策</strong>,不能只列名字。</p></blockquote><p><strong>Q5:上下文工程是什么?</strong></p><blockquote><p>「Agent 的记忆就是上下文窗口,所以上下文的组织方式比提示词措辞重要得多。核心三条:工具结果要摘要后再进上下文;状态要写清为什么而不只是做了什么;要给 Agent 够用就停的信号,否则成本闸门也没用。」</p></blockquote><h2 id="🎯-实战清单" tabindex="-1">🎯 实战清单 <a class="header-anchor" href="#🎯-实战清单" aria-label="Permalink to &quot;🎯 实战清单&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 能说清 Agent 的四个部件与各自的工程形态</span></span>
<span class="line"><span>✅ 循环有四种终止方式,成本上限不能省</span></span>
<span class="line"><span>✅ 工具设计优先于 prompt 设计</span></span>
<span class="line"><span>✅ 上下文三原则(摘要 / 写理由 / 够用就停)</span></span>
<span class="line"><span>✅ 有&quot;什么时候不该用 Agent&quot;的判据</span></span>
<span class="line"><span>✅ 单 Agent + 更多工具 作为默认选择</span></span>
<span class="line"><span>✅ 状态所有权表 + 结构化交接契约</span></span>
<span class="line"><span>✅ 失败模式清单(能说根因和对策)</span></span></code></pre></div><h2 id="🔗-延伸阅读" tabindex="-1">🔗 延伸阅读 <a class="header-anchor" href="#🔗-延伸阅读" aria-label="Permalink to &quot;🔗 延伸阅读&quot;">​</a></h2><ul><li><a href="./../llm/5-function-calling">Function Calling / Tool Use</a> — 工具调用的完整链路与避坑</li><li><a href="./3-multi-agent">Multi-Agent 多智能体系统</a> — Supervisor / Swarm / Pipeline 实现</li><li><a href="./4-memory">Memory 机制</a> — 短期 / 长期 / 语义记忆</li><li><a href="./5-reflection">反思机制 + Human-in-the-Loop</a> — 反思与人工介入</li><li><a href="/agent/projects/5-ai-film-production-agents">影视 Agent 流水线:六个 Agent 如何配合</a> — 本文原理在真实场景的落地</li><li><a href="/agent/projects/5-ai-film-production">AI 短剧生产平台</a> — 平台架构与产品结构</li><li><a href="/agent/projects/5-ai-film-production-impl">AI 影视开发流程 · 具体实现</a> — 代码实现</li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>Agent 的最小模型是 <strong>LLM + 工具 + 状态 + 循环</strong>;决策质量靠模型,你能优化的是工具和状态。</li><li>LLM 在循环里只能决定<strong>调哪个工具、是否结束、下一轮输入</strong> —— 它不负责业务逻辑,那些必须在工具里。</li><li><strong>上下文工程 &gt; 提示词</strong>:工具结果摘要、状态写理由、给够用就停的信号。</li><li><strong>能写 if/else 的别用 Agent</strong>;Agent 的价值在路径不确定的地方。</li><li>多 Agent 前先确认三件事:职责真的不同、能结构化交接、能独立重试。</li><li>多 Agent 的真难点是<strong>状态所有权、交接契约、冲突裁决</strong>,不是画图连线。</li><li><strong>失败模式清单</strong>是 Agent 岗面试里最能体现经验的东西 —— 讲根因和对策,别只背名字。</li></ul>`,75)])])}const b=n(s,[["render",d]]);export{c as __pageData,b as default};
